#!/bin/bash
set -e
APP_DIR="/var/www/maestro-studio"
sudo mkdir -p "$APP_DIR"
cd "$APP_DIR"

echo "=== 1. Aggiornamento server.js ==="
cat << \B64_S\ > server.js.b64

B64_S
base64 -d server.js.b64 > server.js
rm -f server.js.b64

echo "=== 2. Aggiornamento dist/ (Frontend aggiornato) ==="
cat << \B64_D\ > dist.tar.gz.b64

B64_D
base64 -d dist.tar.gz.b64 > dist.tar.gz
tar -xzf dist.tar.gz
rm -f dist.tar.gz.b64 dist.tar.gz

echo "=== 3. Riavvio PM2 (Senza toccare porte o Nginx) ==="
pm2 restart maestro-studio --update-env || PORT=5000 pm2 start server.js --name "maestro-studio"
pm2 save

echo "=== AGGIORNAMENTO COMPLETATO CON SUCCESSO! ==="
